ROWS = [
dict(id="T013", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'Conformal Limits of Critical Square-Lattice Random-Cluster Interfaces' (5 Oct 2026, github.com/openai/math), Theorem 1.1, claims chordal SLE(kappa) convergence and nested whole-plane CLE(kappa) convergence for every fixed 1 <= q <= 4 with kappa = 4 pi / arccos(-sqrt(q)/2). AI-written; no independent check found. Replacement row to be screened.", d="SM", t="Conformal invariance of the critical FK random-cluster model for 1 ≤ q ≤ 4",
 s="For the critical random-cluster model on Z^2 with cluster weight q ∈ [1, 4], interfaces converge to SLE(κ) with κ = 4π / arccos(−√q/2) (κ = 6 at q = 1, 16/3 at q = 2, 4 at q = 4) and the full loop ensemble converges to CLE(κ).",
 src="O. Schramm, Conformally invariant scaling limits: an overview and a collection of problems, Proc. ICM 2006; S. Smirnov, Discrete complex analysis and probability, Proc. ICM 2010",
 loc="Schramm 2006, the FK conjecture in Section 2 (to verify)",
 url="https://arxiv.org/abs/math/0602151",
 why="One statement covering percolation (q = 1), Ising (q = 2) and the 3- and 4-state Potts models; only q = 2 is done.",
 st="q = 2 proved (Smirnov 2010; Chelkak–Smirnov 2012; Kemppainen–Smirnov 2019). For 1 ≤ q ≤ 4: continuity of the transition (Duminil-Copin–Sidoravicius–Tassion 2017) and rotational invariance (Duminil-Copin–Kozlowski–Krachun–Manolescu–Oulamara 2020). For q > 4 the transition is discontinuous (Duminil-Copin–Gagnebin–Harel–Manolescu–Tassion 2016). For q = 4 the loops converge to CLE(4) (Averous–Duminil-Copin–He–Lammers–Manolescu, arXiv:2610.08507, Oct 2026, unrefereed). Conformal invariance is open for q ∈ [1, 4) other than q = 2; its q = 1 case is T002."),
dict(id="T014", d="PERC", t="Mean-field critical behaviour of percolation in dimensions 7 to 10",
 s="Nearest-neighbour Bernoulli percolation on Z^d satisfies the triangle condition for every d > 6, so its critical exponents take their mean-field values (β = 1, γ = 1, δ = 2, η = 0) for all d ≥ 7.",
 src="M. Aizenman and C. M. Newman, Tree graph inequalities and critical behavior in percolation models, J. Stat. Phys. 36 (1984); G. Slade, The Lace Expansion and its Applications (Springer, 2006)",
 loc="Fitzner and van der Hofstad, Electron. J. Probab. 22 (2017), introduction: the proved range d ≥ 11 and the open range 7 to 10",
 why="Six is the upper critical dimension; the gap between d = 7 and the proved d ≥ 11 is a known hard limit of the lace expansion.",
 st="Proved for d ≥ 11 (Fitzner–van der Hofstad 2017; Hara–Slade 1990 for d ≥ 19) and for spread-out models in every d > 6 (Hara–Slade 1990; Hara–van der Hofstad–Slade 2003). A renormalisation framework makes mean-field behaviour semi-decidable (Blanc-Renaudie, arXiv:2609.20764); its abstract does not claim d = 7 to 10. Open for nearest-neighbour Z^7 to Z^10; it would settle T001 there."),
dict(id="T015", d="SM", t="The self-avoiding walk in dimensions 2 to 4 is at least diffusive",
 s="For the self-avoiding walk on Z^d with 2 ≤ d ≤ 4, the mean-square end-to-end distance satisfies E|ω(n)|² ≥ cn; in d = 3 it grows like n^{2ν} with ν ≈ 0.588, and in d = 4 like n (log n)^{1/4}.",
 src="N. Madras and G. Slade, The Self-Avoiding Walk (Birkhäuser, 1993)",
 loc="Chapter 1 and the open problems listed there (to verify)",
 why="That a self-repelling walk spreads at least as fast as simple random walk looks obvious and is unproved; it is the standard measure of how little is known about SAW in low dimensions.",
 st="Diffusive with Brownian limit for d ≥ 5 (Hara–Slade 1992). In 2 ≤ d ≤ 4: sub-ballistic, E|ω(n)|² = o(n²) (Duminil-Copin–Hammond 2013), and the polynomial lower bound E|ω(n)|² ≥ c n^{4/(3d)} (Madras 2014). In d = 4 the log^{1/4} correction is proved for the susceptibility of the weakly self-avoiding walk (Bauerschmidt–Brydges–Slade 2015); the mean-square displacement n (log n)^{1/4} is open even there."),
dict(id="T016", d="IPS", t="Planar diffusion-limited aggregation has dimension less than 2",
 s="The diffusion-limited aggregation cluster in Z^2 with n particles has radius at least n^{1/2+ε} for some ε > 0, so its growth dimension is strictly below 2 (numerically about 1.71).",
 src="T. A. Witten and L. M. Sander, Diffusion-limited aggregation, a kinetic critical phenomenon, Phys. Rev. Lett. 47 (1981); H. Kesten, How long are the arms in DLA?, J. Phys. A 20 (1987)",
 why="DLA is the best-known growth model without a rigorous theory; the only general bound is almost forty years old.",
 st="Kesten (1987, 1990) proved the radius is at most C n^{2/3} in d = 2 and C n^{2/d} in d ≥ 3; Benjamini–Yadin (arXiv:1705.06095, 2017) improve the bound on Z^3 to C (n log n)^{1/2}. Losev–Smirnov (arXiv:2307.14931) extend Kesten's estimate to the dielectric breakdown model in two and three dimensions. The trivial lower bound n^{1/2} has never been improved, so it is not even known that DLA is not a disc-like blob.",
 loc="Kesten 1987, J. Phys. A 20, L29 (the upper bound); the model is Witten–Sander 1981"),
dict(id="T017", d="RG", t="The satisfiability threshold of random k-SAT for small k",
 s="For each k ≥ 3, random k-SAT on n variables with αn clauses has a sharp threshold at a constant α_k independent of n, equal to the one-step replica-symmetry-breaking prediction (α_3 ≈ 4.2667).",
 src="E. Friedgut, Sharp thresholds of graph properties, and the k-sat problem, J. Amer. Math. Soc. 12 (1999); M. Mézard, G. Parisi and R. Zecchina, Analytic and algorithmic solution of random satisfiability problems, Science 297 (2002)",
 why="The canonical random constraint satisfaction problem; the cavity-method prediction is proved only for large k.",
 st="Proved for k ≥ k_0 (Ding–Sly–Sun 2015). For k = 3 Friedgut's threshold might depend on n. The lower bound 3.52 (Kaporis–Kirousis–Lalas 2006; Hajiaghayi–Sorkin 2003); the upper bound 4.4898 (Díaz–Kirousis–Mitsche–Pérez-Giménez 2009) was lowered to 4.268 by Vorobyev (arXiv:2610.10599, Oct 2026: rigorous, the last step a finite check in exact fractions, also encoded in Lean 4; unrefereed), against the one-step RSB value 4.2667. So 3.52 ≤ α_3 ≤ 4.268. Open for small k."),
dict(id="T018", x='SOLVED: a proof is presented by P. Bizeul, B. Klartag and J. Lehec, Presenting a proof of the Kannan–Lovász–Simonovits conjecture, arXiv:2610.05474 (4 Oct 2026), using a criterion of Song and Zhang. Read from the arXiv abstract 14 Oct; flagged first by the w672 audit.', d="COMB", t="The Kannan–Lovász–Simonovits conjecture",
 s="There is a universal c > 0 such that every isotropic log-concave probability measure on R^n has Cheeger constant at least c, independent of n (equivalently, its Poincaré constant is bounded by a universal multiple of the covariance operator norm).",
 src="R. Kannan, L. Lovász and M. Simonovits, Isoperimetric problems for convex bodies and a localization lemma, Discrete Comput. Geom. 13 (1995)",
 why="The central conjecture of high-dimensional convex probability; it implies the thin-shell conjecture and, through Eldan–Klartag, the slicing problem.",
 st="Bounds improved to n^{o(1)} (Chen, Geom. Funct. Anal. 31 (2021)), (log n)^5 (Klartag–Lehec, Geom. Funct. Anal. 32 (2022)) and about √(log n) (Klartag, Logarithmic bounds for isoperimetry and slices of convex sets, Ars Inveniendi Analytica 2023). The slicing problem was settled by Klartag–Lehec in 2024 using Guan's bound; KLS itself is open."),
dict(id="T019", d="RW", t="Glauber dynamics for proper colourings mixes rapidly when q ≥ Δ + 2",
 s="For every graph of maximum degree Δ and every q ≥ Δ + 2, Glauber dynamics on proper q-colourings mixes in time O(n log n).",
 src="M. Jerrum, A very simple algorithm for estimating the number of k-colorings of a low-degree graph, Random Structures Algorithms 7 (1995)",
 loc="Jerrum proves O(n log n) mixing for q > 2Δ; the threshold Δ + 2 is the standing conjecture, not a statement of that paper",
 why="The best-known open problem on the mixing of spin-system Markov chains; Δ + 2 is where the chain is ergodic on every graph.",
 st="Known for q > 2Δ (Jerrum 1995; Salas–Sokal 1997), q > (11/6)Δ (Vigoda 1999), q > (11/6 − ε)Δ (Chen–Delcourt–Moitra–Perarnau–Postle 2019), and q ≥ 1.809Δ for the flip dynamics (Carlson–Vigoda, arXiv:2407.04870, 2024); much better on trees or large girth (Hayes–Vigoda; spectral independence, Chen–Liu–Vigoda 2020–21). For every δ > 0 and large Δ, q ≥ (1 + δ)Δ gives O(n log n) mixing on graphs of girth at least 7 (Jain–Mizgerd–Vigoda, arXiv:2604.11938, Apr 2026) and rapid mixing on graphs of girth at least 5 (Chen–Liu, arXiv:2608.25491, Aug 2026). Open at Δ + 2 on general graphs."),
dict(id="T020", x='SOLVED: replica symmetry holds for every (β, h) below the de Almeida–Thouless line with uniform h > 0 (P. Lopatto, Replica symmetry up to the de Almeida–Thouless line in the Sherrington–Kirkpatrick model, arXiv:2604.11921, Apr 2026); with Toninelli 2002 the line is settled. Read from the arXiv abstract 14 Oct; flagged first by the w672 audit.', d="SM", t="The de Almeida–Thouless line of the Sherrington–Kirkpatrick model",
 s="For the Sherrington–Kirkpatrick model at inverse temperature β with external field h, the replica-symmetric solution holds (the Parisi measure is a point mass) exactly when β² E[sech⁴(β√q Z + h)] ≤ 1, where q solves q = E[tanh²(β√q Z + h)].",
 src="J. R. L. de Almeida and D. J. Thouless, Stability of the Sherrington–Kirkpatrick solution of a spin glass model, J. Phys. A 11 (1978); M. Talagrand, Mean Field Models for Spin Glasses, Vol. II (Springer, 2011)",
 loc="Talagrand 2011, research problem on the AT line (to verify)",
 why="With the Parisi formula proved (Talagrand 2006; Panchenko 2013), the location of the replica-symmetry-breaking transition is the best-known remaining question about the SK model.",
 st="Replica symmetry breaking above the AT line is proved (Toninelli 2002). Replica symmetry below it is known away from the line (Talagrand; Jagannath–Tobasco, Probab. Theory Related Fields 167 (2017)) and for centred Gaussian external fields (W.-K. Chen, Electron. Commun. Probab. 26 (2021)). Open in full."),
dict(id="T021", d="COMB", t="The Friedgut–Kalai entropy–influence conjecture",
 s="There is a universal C such that every Boolean function f: {−1,1}^n → {−1,1} satisfies Σ_S f̂(S)² log(1/f̂(S)²) ≤ C Σ_S |S| f̂(S)²: the spectral entropy is at most C times the total influence.",
 src="E. Friedgut and G. Kalai, Every monotone graph property has a sharp threshold, Proc. Amer. Math. Soc. 124 (1996)",
 why="It would say that a function of small total influence is concentrated on few Fourier coefficients, with consequences for learning and sharp thresholds; the best-known open problem of Boolean Fourier analysis.",
 st="Proved for symmetric functions and read-once decision trees (O'Donnell–Wright–Zhou, ICALP 2011), for random linear threshold functions (Chakraborty–Karmalkar–Kundu–Lokam–Saurabh, arXiv:1903.11635) and for other classes; general bounds with extra factors are in Chakraborty–Kulkarni–Lokam–Saurabh (Theoret. Comput. Sci. 2016). Kelman–Kindler–Lifshitz–Minzer–Safra (FOCS 2020) show that the spectrum of a constant-variance Boolean f is concentrated on 2^{O(I[f] log I[f])} characters; removing the log I[f] factor would essentially give the conjecture. X. Han, A new bound for the Fourier-entropy-influence conjecture, Combinatorica 45 (2025), DOI 10.1007/s00493-024-00133-z, proves H(f) ≤ O(I(f) + Σ_k I_k(f) log(1/I_k(f))); the extra term is not bounded by a multiple of I(f) in general. The weaker Fourier min-entropy–influence conjecture is also open."),
dict(id="T022", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'No bigeodesics in planar first-passage percolation' (24 Sep 2026, github.com/openai/math) claims the full statement, under the same minimum-of-four second-moment condition and with no assumption on the limit shape. AI-written; the release's Lean files do not cover this theorem and no independent check was found. Replacement row to be screened.", d="PERC", t="No bi-infinite geodesics in planar first-passage percolation",
 s="In first-passage percolation on Z^2 with iid nonnegative continuous edge weights satisfying E min(t_1, …, t_4)^2 < ∞ (the minimum of four independent copies), almost surely no bi-infinite geodesic exists.",
 src="H. Kesten, Aspects of first passage percolation, École d'Été de Probabilités de Saint-Flour XIV (1986), where the question is attributed to Furstenberg; A. Auffinger, M. Damron and J. Hanson, 50 Years of First-Passage Percolation (2017)",
 loc="Auffinger–Damron–Hanson 2017, Chapter 4 (to verify)",
 url="https://arxiv.org/abs/1511.03262",
 why="It is the FPP form of the absence of non-trivial ground states in disordered ferromagnets, and part of the KPZ picture of geodesics.",
 st="Proved for exponential last-passage percolation (Basu–Hoffman–Sly 2022; Balázs–Busani–Seppäläinen 2020) and for fixed directions under curvature assumptions (Licea–Newman 1996; Damron–Hanson 2017). Open for FPP."),
dict(id="T023", d="GF", t="Random planar maps embedded conformally converge to Liouville quantum gravity",
 s="Uniform random triangulations (and quadrangulations), embedded in the plane by circle packing or by the Tutte (harmonic) embedding, with the counting measure on vertices suitably rescaled, converge to √(8/3)-Liouville quantum gravity. Maps decorated by critical statistical-mechanics models are expected to converge to γ-LQG with γ fixed by the model; that is the wider programme.",
 c="The precise target is the uniform-map case, with the topology (weak convergence of the vertex measure, and the normalisation of the embedding) stated as in the source. Spanning-tree-weighted maps (γ = √2) were done in October 2026 (Holden; Holden–Yu) and no longer count toward the open part.",
 src="B. Duplantier and S. Sheffield, Liouville quantum gravity and KPZ, Invent. Math. 185 (2011); J. Miller and S. Sheffield, Liouville quantum gravity and the Brownian map I–III (2015–2021)",
 loc="to verify",
 why="The conformal half of two-dimensional quantum gravity: the metric half (convergence to the Brownian map) is proved, the embedding half is not.",
 st="Known: Gromov–Hausdorff convergence to the Brownian map (Le Gall 2013; Miermont 2013) and its identification with √(8/3)-LQG (Miller–Sheffield); convergence of uniform triangulations under the Cardy embedding (Holden–Sun, arXiv:1905.13207); Tutte embedding of mated-CRT maps (Gwynne–Miller–Sheffield 2021). For spanning-tree-weighted maps (γ = √2) the Tutte embedding (Holden, arXiv:2610.10501) and circle packing and Riemann uniformization (Holden–Yu, arXiv:2610.10505), both Oct 2026, converge to √2-LQG. Circle packing and the Tutte embedding of uniform maps are open."),
dict(id="T024", d="RW", t="Cutoff for random walk on vertex-transitive expanders",
 s="Lazy (or continuous-time) simple random walk on every sequence of vertex-transitive expanders (bounded degree, spectral gap bounded below, size tending to infinity) has cutoff in total variation.",
 c="Statement as usually quoted; source and current status to verify, including whether a transitive counterexample to Peres's product condition is known.",
 src="Y. Peres, problem posed at the AIM workshop on sharp thresholds for mixing times (2004); E. Lubetzky and A. Sly, Cutoff phenomena for random walks on random regular graphs, Duke Math. J. 153 (2010)",
 loc="to verify",
 why="Cutoff is proved for random regular graphs and Ramanujan graphs without a structural explanation; transitivity is the natural setting for a general theorem.",
 st="Known for random regular graphs (Lubetzky–Sly 2010), Ramanujan graphs (Lubetzky–Peres 2016), random Cayley graphs of many groups (Hermon–Olesker-Taylor 2021) and explicit families (Lubetzky–Sly, arXiv:1003.3515). Without transitivity the product condition does not imply cutoff (Aldous; Pak). Open for transitive expanders."),
dict(id="T025", d="SM", t="A spin-glass phase for the three-dimensional Edwards–Anderson model",
 s="The Edwards–Anderson spin glass on Z^3 with symmetric (for example Gaussian) couplings has a low-temperature spin-glass phase: for large β, the overlap of two replicas drawn independently from the Gibbs measure in a box with periodic boundary conditions does not converge to 0 in law as the box grows.",
 c="The structure of that phase (replica symmetry breaking versus the droplet picture, the number of ground-state pairs) is a further open question; statement and source to verify.",
 src="S. F. Edwards and P. W. Anderson, Theory of spin glasses, J. Phys. F 5 (1975); C. M. Newman and D. L. Stein, Spin Glasses and Complexity (Princeton, 2013)",
 why="The short-range spin glass is the hardest disordered system of statistical mechanics, and even its transition is unproved.",
 st="Open. Known: uniqueness at high temperature; results on ground states in two dimensions and half-planes (Newman–Stein; Arguin–Damron–Newman–Stein, arXiv:0911.4201); a zero-temperature form of spin-glass order (Chatterjee, arXiv:2301.04112). Positive-temperature spin-glass order is proved on the diamond hierarchical (Migdal–Kadanoff) lattice of effective dimension 3 (Pei, arXiv:2609.38220, Sep 2026), not on Z^3. Pei (arXiv:2609.22301) proves percolation of the blue clusters of the Chayes–Machta–Redner representation in the high-dimensional limit, and for ±1 couplings in d = 7 to 12 with computer assistance; the density imbalance that would give spin-glass order is left open. No proof of a positive-temperature transition in d = 3."),
]
